var quantity="",gallery=$(".gallery-slide.owl-carousel");function gallerySlide(){gallery.owlCarousel({autoplay:!1,loop:!1,nav:!1,dots:!1,margin:0,items:1,animateOut:"fadeOut",smartSpeed:1500,mouseDrag:!1,touchDrag:!1,pullDrag:!1}).css({opacity:1})}$(".nav-controller").on("click","button",function(){var t=$(this).attr("data-target");gallery.trigger("to.owl.carousel",t)}),$(".zoom-trigger").each(function(){$(this).zoom({url:$(this).attr("href"),magnify:3.5})}),$(".quantity .increment").on("click",function(t){quantity++,$(".quantity .qty").val(quantity),t.preventDefault()}),$(".quantity .decrement").on("click",function(t){quantity>1&&quantity--,$(".quantity .qty").val(quantity),t.preventDefault()}),$(".quantity .qty").on("input",function(){newValue=$(this).val(),quantity=newValue});var related_products=$(".relateds-contain");function related_products_slide(){related_products.owlCarousel({autoplay:!1,loop:!1,nav:!1,dots:!1,margin:50,responsive:{0:{autoplay:!0,loop:!0,items:2,margin:10},768:{items:4}}}).css({opacity:1})}$(()=>{gallerySlide(),quantity=$(".quantity .qty").val(),related_products_slide()});